<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\CoupureElectrique;use App\Models\Quartier;use Illuminate\Http\Request;class CoupureController extends Controller{private function data(Request $r):array{return $r->validate(['quartier_id'=>'required|exists:quartiers,id','titre'=>'required|string|max:255','description'=>'nullable|string','type'=>'required|string','statut'=>'required|string','cause'=>'nullable|string','date_debut'=>'nullable|date','date_fin_estimee'=>'nullable|date|after_or_equal:date_debut','adresse'=>'nullable|string|max:255','latitude'=>'nullable|numeric|between:-90,90','longitude'=>'nullable|numeric|between:-180,180'])+['source'=>'admin','actif'=>$r->boolean('actif')];}public function index(){return view('admin.coupures.index',['coupures'=>CoupureElectrique::with('quartier')->latest()->get()]);}public function create(){return view('admin.coupures.form',['coupure'=>new CoupureElectrique,'quartiers'=>Quartier::all()]);}public function store(Request $r){CoupureElectrique::create($this->data($r));return redirect()->route('admin.coupures.index');}public function show(CoupureElectrique $coupure){return view('admin.coupures.show',['coupure'=>$coupure->load('quartier')->loadCount('signalements')]);}public function edit(CoupureElectrique $coupure){return view('admin.coupures.form',['coupure'=>$coupure,'quartiers'=>Quartier::all()]);}public function update(Request $r,CoupureElectrique $coupure){$coupure->update($this->data($r));return redirect()->route('admin.coupures.show',$coupure);}public function destroy(CoupureElectrique $coupure){$coupure->delete();return redirect()->route('admin.coupures.index');}}
